import { makeObservable, observable } from 'mobx';
import { getToken } from '../utils/getToken';

class UserStore {
  session: {
    expires?: string;
    user?: {
      email: string;
      id: string;
      image: string;
      name: string;
      freeQuota: number;
      invite_code: string;
    };
    coinCount?: number;
  } = {};

  loading: boolean = false;

  constructor() {
    makeObservable(this, {
      session: observable,
      loading: observable,
    });
  }

  async loadSession() {
    this.loading = true;
    const s = await chrome.storage.local.get(['cookie']);
    const result = s as { cookie: string };
    // 从 result.cookie 中解析出 名为 next-auth.session-token 的 cookie
    const token = await getToken();

    const headers: any = {
      Cookie: result.cookie,
      'Content-Type': 'application/json',
      token: token,
    };
    try {
      const res = await fetch('https://zhinang.ai/api/session', {
        headers,
      });
      const data = await res.json();
      if (data?.user) {
        this.session.user = data.user;
        this.session.coinCount = data.coinCount;
      }
    } catch (error) {}
    this.loading = false;
  }
}

export default new UserStore();
