export async function getToken() {
  const s = await chrome.storage.local.get(['cookie']);
  const result = s as { cookie: string };
  if (!result.cookie) {
    return '';
  }
  const token = result.cookie
    .split(';')
    .map((c) => c.trim())
    .find((c) => c.startsWith('next-auth.session-token'))
    ?.split('=')[1];
  return token;
}
